import{_ as t,o as e,c as o,a3 as r}from"./chunks/framework.DsQ8uxR7.js";const _=JSON.parse('{"title":"演員座標與縮放","description":"","frontmatter":{"title":"演員座標與縮放","order":6},"headers":[],"relativePath":"tc/tutorial/actor-coordinate-and-scaling.md","filePath":"tc/tutorial/actor-coordinate-and-scaling.md","lastUpdated":1778242448000}'),n={name:"tc/tutorial/actor-coordinate-and-scaling.md"};function i(c,a,d,l,s,h){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="演員座標與縮放" tabindex="-1">演員座標與縮放 <a class="header-anchor" href="#演員座標與縮放" aria-label="Permalink to &quot;演員座標與縮放&quot;">​</a></h1><h2 id="場景座標系" tabindex="-1">場景座標系 <a class="header-anchor" href="#場景座標系" aria-label="Permalink to &quot;場景座標系&quot;">​</a></h2><p>對話中，演員的座標決定了他們相對於場景的位置。原點位於左上角，X 軸向右增加，Y 軸向下增加。</p><h2 id="演員縮放比例" tabindex="-1">演員縮放比例 <a class="header-anchor" href="#演員縮放比例" aria-label="Permalink to &quot;演員縮放比例&quot;">​</a></h2><p>演員的縮放比例決定了他們在場景中的大小。原點位於左上角，X 軸向右增加，Y 軸向下增加。</p><h2 id="參考解析度比例" tabindex="-1">參考解析度比例 <a class="header-anchor" href="#參考解析度比例" aria-label="Permalink to &quot;參考解析度比例&quot;">​</a></h2><p>為了適應不同解析度比例的裝置，演員的座標和縮放比例是相對的，而不是絕對的。因此在專案中應確定統一的解析度比例作為參考，並按照該比例設定演員的座標和縮放比例。</p><p>推薦使用 <code>1920x1080</code> 作為參考解析度比例，這樣可以兼顧電腦和手機等不同裝置。</p><p>如果你的目標裝置解析度比例是固定的（如一些遊戲機裝置），那麼你可以使用該裝置的解析度比例作為參考，無需考慮其他裝置。</p>',9)])])}const u=t(n,[["render",i]]);export{_ as __pageData,u as default};
